<?php
require_once "../includes/security.php";
startSecureSession();
require_once "../includes/db_connect.php"; require_once "../includes/permissions.php"; require_once "../includes/receiving_schema.php"; require_once "../includes/receiving_attachments.php"; require_once "../includes/activity_log.php"; require_once "../includes/date_helpers.php";
if(!isset($_SESSION['username'])){header("Location:index.html");exit;} if(!hasPermission($mysqli,"receiving_add")){die("Access denied");} ensureReceivingSchema($mysqli);
$username=$_SESSION['username']; $role=$_SESSION['role']??"UNKNOWN"; $error="";
function riE($v){return htmlspecialchars((string)($v??""),ENT_QUOTES,"UTF-8");}
if($_SERVER['REQUEST_METHOD']==="POST"){
 $date=appNormalizeDateInput($_POST['received_date']??""); $by=trim($_POST['received_by']??""); $type=trim($_POST['item_type']??""); $item=trim($_POST['item_name']??""); $part=trim($_POST['part_number']??""); $serial=trim($_POST['serial_number']??""); $brand=trim($_POST['brand']??""); $desc=trim($_POST['description']??""); $qty=max(1,(int)($_POST['quantity']??1)); $rack=trim($_POST['rack_location']??""); $remark=trim($_POST['remark']??"");
 if(!$date||$by===""||$type===""||$item===""||$rack===""){$error="Received date, received by, item type, item name and rack/location are required.";}
 $stored="";$original="";$mime="";$size=0;
 if($error === "" && isset($_FILES['attachment'])){
    $upload = receivingStoreAttachment($_FILES['attachment']);
    if(!$upload['success']){
        $error = $upload['error'];
    } else {
        $stored = $upload['stored_name'];
        $original = $upload['original_name'];
        $mime = $upload['mime'];
        $size = (int)$upload['size'];
    }
 }
 if($error===""){$empty="";$stmt=$mysqli->prepare("INSERT INTO receiving_records(received_date,received_by,item_type,item_name,part_number,serial_number,brand,description,quantity,rack_location,purpose_route,purpose_detail,client_name,project_name,remark,attachment_file_name,attachment_original_name,attachment_mime,attachment_size,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)");$stmt->bind_param("ssssssssisssssssssis",$date,$by,$type,$item,$part,$serial,$brand,$desc,$qty,$rack,$empty,$empty,$empty,$empty,$remark,$stored,$original,$mime,$size,$username);if($stmt->execute()){logActivity($mysqli,$username,$role,"ITEM RECEIVE","Received item: $item; rack: $rack");header("Location:item_receive.php?saved=1");exit;}if($stored!==""){receivingDeleteAttachment($stored);}$error="Unable to save item: ".$stmt->error;}
}
?>
