ass="form-label">Item Name / Model *</label><input name="item_name" class="form-control" required></div><div class="col-md-4 mb-3"><label class="form-label">Part Number</label><input name="part_number" class="form-control"></div><div class="col-md-4 mb-3"><label class="form-label">Serial / Asset ID</label><input name="serial_number" class="form-control"></div><div class="col-md-4 mb-3"><label class="form-label">Brand</label><input name="brand" class="form-control"></div><div class="col-md-4 mb-3"><label class="form-label">Quantity *</label><input type="number" min="1" name="quantity" value="1" class="form-control" required></div><div class="col-md-4 mb-3"><label class="form-label">Rack / Location *</label><input name="rack_location" class="form-control" required></div><div class="col-12 mb-3"><label class="form-label">Description</label><textarea name="description" class="form-control" rows="3"></textarea></div><div class="col-12 mb-3"><label class="form-label">Attachment (PNG, JPG, PDF, Word, Excel, TXT — max 100 MB)</label><input type="file" name="attachment" class="form-control" accept=".png,.jpg,.jpeg,.gif,.webp,.pdf,.doc,.docx,.xls,.xlsx,.txt"></div><div class="col-12 mb-3"><label class="form-label">Remark</label><textarea name="remark" class="form-control" rows="3"></textarea></div></div><button class="btn btn-warning"><i class="fa fa-save"></i> Save Received Item</button></form></div></div></main><?php include "layout/footer.php";?></body></html>
